  <p class=MsoNormal align=center style='text-align:center;line-height:normal'><span
  style='font-size:12.0pt;font-family:"Times New Roman",serif'>Başkanvekili</span></p>
  <p class=MsoNormal align=center style='text-align:center;line-height:normal'><span
  style='font-size:12.0pt;font-family:"Times New Roman",serif'>Şevket MÜFTÜGİL</span></p>
  </td>
