font-family:&quot;Times New Roman&quot;,&quot;serif&quot;;color:black">14.12.2009 günlü, 5941 sayılı Çek Kanunu'nun 5. maddesinin (1) numaralı fıkrasının birinci ve ikinci tümcelerinin Anayasa'nın 38. maddesine aykırılığı savıyla iptali istemidir.</span></p>", "kararTarihi": "2010-02-25", "yayinTarihi": "2011-12-22T00:00:00", "basvuranOzel": "cdbee00b-3abb-b0f0-2808-7ad7426ae4ba", "anayasaDonemi": "6e2d0518-66ed-4416-9bee-ceeecde49367", "basinDuyurusu": false, "basvuranGenel": "1ccf221b-4a82-bad5-ab72-ca755ea44c65", "sozluAciklama": "false", "highlightCount": 0, "ilkincelemeTarihi": "2010-02-25", "resmiGazeteSayisi": 0, "kararTuruDosyaSonucu": "2e852fa3-a159-2de4-5ab3-d6e0434fa162", "kararTuruDosyaSonucuLabel": "İlk - Ret vd.", "kararYururlugundeErteleme": false, "normDenetimiIncelemeGerekceleri": [{"karsiOy": false, "normTarihi": "2009-12-14", "durumParamId": "5a1d555f-e4b6-499b-9b79-b2d28b3dc6c5", "farkliGerekce": false, "maddeNumarasi": null, "ertelemeSuresi": null, "maddeNumaralari": [{"bent": "1", "diger": null, "fikra": "1", "altBent": null, "maddeNumarasi": "5"}], "normTuruParamId": "53ab265d-7e56-47e0-9e63-f8ee6a4a4611", "maddeNumarasiList": null, "normNumaraAdParamId": "e2d1211f-9d71-50af-e6c3-d0d6466e3846", "kararYururlulukDurumu": "yok", "sonucGerekcesiParamId": "a25c017e-4835-21b8-30ce-b85613d20fab", "dayanakAnayasaHukumList": [{"hukum": "1982/2"}], "normDenetimiKarsiOyRelList": null, "incelemeturuKarsonucuParamId": "be1c069d-fc50-cc2f-7d43-bde063ae8263", "normDenetimiFarkliGerekceRelList": null}, {"karsiOy": false, "normTarihi": "2009-12-14", "durumParamId": "5a1d555f-e4b6-499b-9b79-b2d28b3dc6c5", "farkliGerekce": false, "maddeNumarasi": null, "ertelemeSuresi": null, "maddeNumaralari": [{"bent": "2", "diger": null, "fikra": "1", "altBent": null, "maddeNumarasi": "5"}], "normTuruParamId": "53ab265d-7e56-47e0-9e63-f8ee6a4a4611", "maddeNumarasiList": null, "normNumaraAdParamId": "e2d1211f-9d71-50af-e6c3-d0d6466e3846", "kararYururlulukDurumu": "yok", "sonuc